# L1C UNITARY TEST
# 1. Cross validation of my L1C outputs with the teacher outputs. The L1C points are stored in a
#    different order in each execution (ATBD 9.1.1.1), so both outputs are sorted by lat/lon before comparing
# 2. SSD (spatial sampling distance) of the L1B grid for the central row (ALT line 50) and the central
#    column (ACT column 75), compared with the 100 m of the L1C MGRS grid
# The L1B/L1C grid plots and the L1C TOA plots are generated by the L1C module (l1c.plotL1cGrid)

import os
import numpy as np
import matplotlib.pyplot as plt
from geopy.distance import geodesic
from common.io.l1cProduct import readL1c
from common.io.readGeodetic import readGeodetic
from config.globalConfig import globalConfig

# Directories
dir_mine = r"C:/Users/alexe/Downloads/EODP/EODP_TER_2021/EODP-TS-L1C/output_AEC_3"
dir_ref = r"C:/Users/alexe/Downloads/EODP/EODP_TER_2021/EODP-TS-L1C/output"
dir_gm = r"C:/Users/alexe/Downloads/EODP/EODP_TER_2021/EODP-TS-L1C/input/gm_alt100_act_150"
dir_fig = r"C:/Users/alexe/Downloads/EODP/EODP_TER_2021/EODP-TS-L1C/figures_AEC"

bands = ['VNIR-0', 'VNIR-1', 'VNIR-2', 'VNIR-3']
threshold = 1e-3  # [%] maximum relative difference allowed (guide to the subject)

if not os.path.isdir(dir_fig):
    os.makedirs(dir_fig)

# -------------------------------------------------------------------------------
# 1. Cross validation with the reference outputs
# -------------------------------------------------------------------------------
results = []
for band in bands:
    toa_mine, lat_mine, lon_mine = readL1c(dir_mine, 'l1c_toa_' + band + '.nc')
    toa_ref, lat_ref, lon_ref = readL1c(dir_ref, 'l1c_toa_' + band + '.nc')

    if toa_mine.size != toa_ref.size:
        line = band + ': different number of L1C points, mine = ' + str(toa_mine.size) + ', ref = ' + str(toa_ref.size)
        print(line)
        results.append(line)
        continue

    # Sort both outputs by latitude and then longitude so the points are in the same order
    idx_mine = np.lexsort((lon_mine, lat_mine))
    idx_ref = np.lexsort((lon_ref, lat_ref))

    line = band + ': ' + str(toa_mine.size) + ' L1C points'
    result = 'PASS'
    for name, mine, ref in [('lat', lat_mine[idx_mine], lat_ref[idx_ref]),
                            ('lon', lon_mine[idx_mine], lon_ref[idx_ref]),
                            ('toa', toa_mine[idx_mine], toa_ref[idx_ref])]:
        diff = np.abs(mine - ref)
        rel_diff = np.zeros(diff.shape)
        mask = ref != 0
        rel_diff[mask] = diff[mask] / np.abs(ref[mask]) * 100
        if np.max(rel_diff) >= threshold:
            result = 'FAIL'
        line = line + ' | ' + name + ': max abs diff = ' + '%.3e' % np.max(diff) + ', max rel diff = ' + '%.3e' % np.max(rel_diff) + ' %'
    line = line + '  -> ' + result
    print(line)
    results.append(line)

with open(os.path.join(dir_fig, 'l1c_crossvalidation.txt'), 'w') as f:
    f.write('\n'.join(results))

# -------------------------------------------------------------------------------
# 2. SSD of the L1B grid in the central row and column
# -------------------------------------------------------------------------------
lat, lon = readGeodetic(dir_gm, globalConfig().gm_geoloc)
idalt = int(lat.shape[0] / 2)   # central row (ALT line 50)
idact = int(lat.shape[1] / 2)   # central column (ACT column 75)

# Distance between consecutive pixels [m]
ssd_row = np.array([geodesic((lat[idalt, jj], lon[idalt, jj]), (lat[idalt, jj + 1], lon[idalt, jj + 1])).m
                    for jj in range(lat.shape[1] - 1)])   # ACT direction
ssd_col = np.array([geodesic((lat[ii, idact], lon[ii, idact]), (lat[ii + 1, idact], lon[ii + 1, idact])).m
                    for ii in range(lat.shape[0] - 1)])   # ALT direction

for ssd, name, xlabel, title in [(ssd_row, 'ssd_l1b_row' + str(idalt), 'ACT pixel [-]', 'SSD ACT of the L1B grid, row ' + str(idalt)),
                                 (ssd_col, 'ssd_l1b_col' + str(idact), 'ALT pixel [-]', 'SSD ALT of the L1B grid, column ' + str(idact))]:
    fig = plt.figure(figsize=(10, 7))
    plt.plot(ssd, '-b', label='L1B SSD')
    plt.axhline(100, color='r', linestyle='--', label='L1C MGRS grid (100 m)')
    plt.title(title, fontsize=16)
    plt.xlabel(xlabel, fontsize=14)
    plt.ylabel('SSD [m]', fontsize=14)
    plt.legend()
    plt.grid()
    saveas = os.path.join(dir_fig, name + '.png')
    plt.savefig(saveas)
    plt.close(fig)
    print('Saved image ' + saveas)

lines = ['SSD ACT (row ' + str(idalt) + '): mean = %.2f m, min = %.2f m, max = %.2f m' % (np.mean(ssd_row), np.min(ssd_row), np.max(ssd_row)),
         'SSD ALT (column ' + str(idact) + '): mean = %.2f m, min = %.2f m, max = %.2f m' % (np.mean(ssd_col), np.min(ssd_col), np.max(ssd_col)),
         'L1B points = ' + str(lat.size)]
for band in bands:
    toa_mine, lat_mine, lon_mine = readL1c(dir_mine, 'l1c_toa_' + band + '.nc')
    lines.append(band + ': L1C points = ' + str(toa_mine.size) + ', min TOA = %.2f, max TOA = %.2f mW/m2/sr' % (np.min(toa_mine), np.max(toa_mine)))
for line in lines:
    print(line)
with open(os.path.join(dir_fig, 'l1c_ssd.txt'), 'w') as f:
    f.write('\n'.join(lines))